40	    async fn invoke(
41	        &self,
42	        request: ModelRequest,
43	        cancel: CancellationToken,
44	    ) -> Result<BoxStream<'static, Result<ModelEvent, ModelError>>, ModelError> {
45	        let prepared = build_body(&self.cfg, &request)?;
46	        let synthesizing = prepared.synthesizing_output;
47	        let headers = build_headers(&self.cfg);
48	        let url = messages_url(&self.cfg);
49	        let client = self.cfg.http.clone();
50	
51	        let s = stream! {
52	            let send_fut = client
53	                .post(&url)
54	                .headers(headers)
55	                .json(&prepared.body)
56	                .send();
57	
58	            let response = tokio::select! {
59	                biased;
60	                _ = cancel.cancelled() => return,
61	                r = send_fut => match r {
62	                    Ok(r) => r,
63	                    Err(e) => {
64	                        yield Err(ModelError::Transport(e.to_string()));
65	                        return;
66	                    }
67	                },
68	            };
69	
70	            let status = response.status();
71	            if !status.is_success() {
72	                let retry_after_ms = parse_retry_after_ms(response.headers());
73	                let body_bytes = response.bytes().await.unwrap_or_default();
74	                let parsed: Result<serde_json::Value, _> = serde_json::from_slice(&body_bytes);
75	                let (ty, message) = parsed
76	                    .as_ref()
77	                    .ok()
78	                    .map(|v| {
79	                        let ty = v
80	                            .get("error")
81	                            .and_then(|e| e.get("type"))
82	                            .and_then(|t| t.as_str())
83	                            .unwrap_or("")
84	                            .to_owned();
85	                        let msg = v
86	                            .get("error")
87	                            .and_then(|e| e.get("message"))
88	                            .and_then(|m| m.as_str())
89	                            .unwrap_or("")
90	                            .to_owned();
91	                        (ty, msg)
92	                    })
93	                    .unwrap_or_else(|| {
94	                        (
95	                            String::new(),
96	                            String::from_utf8_lossy(&body_bytes).into_owned(),
97	                        )
98	                    });
99	                yield Err(map_error_type(Some(status.as_u16()), &ty, &message, retry_after_ms));
100	                return;
101	            }
102	
103	            let mut event_stream = response.bytes_stream().eventsource();
104	            let mut translator = MessageTranslator::new(synthesizing);
105	
106	            loop {
107	                let next = tokio::select! {
108	                    biased;
109	                    _ = cancel.cancelled() => return,
110	                    n = event_stream.next() => n,
111	                };
112	                match next {
113	                    None => return,
114	                    Some(Err(e)) => {
115	                        yield Err(ModelError::Transport(e.to_string()));
116	                        return;
117	                    }
118	                    Some(Ok(event)) => {
119	                        let parsed: AnthropicEvent = match serde_json::from_str(&event.data) {
120	                            Ok(p) => p,
121	                            Err(parse_err) => {
122	                                // Log structured metadata only — the raw payload
123	                                // may contain user/model/tool content and must
124	                                // not be written to logs.
125	                                tracing::warn!(
126	                                    target: "paigasus::anthropic::sse",
127	                                    %parse_err,
128	                                    event_len = event.data.len(),
129	                                    event_name = %event.event,
130	                                    "unparseable SSE event payload",
131	                                );
132	                                continue;
133	                            }
134	                        };
135	                        match translator.consume(parsed) {
136	                            Err(e) => {
137	                                yield Err(e);
138	                                return;
139	                            }
140	                            Ok(events) => {
141	                                for ev in events {
142	                                    yield ev;
143	                                }
144	                            }
145	                        }
146	                    }
147	                }
148	            }
149	        };
150	
151	        Ok(Box::pin(s))
152	    }
